// One item per photo: the packaging photo (first frame, optional), the product photo (last frame)
// and up to max_reference_photos extra angles of the product (Kling reference images).
const s = $('Set Video Configuration').first().json;
const form = $('Form Submission Trigger').first();
const entries = Object.entries(form.binary || {}).filter(([k, b]) => String(b.mimeType || '').startsWith('image/'));
const byName = (a, b) => String(a.fileName || '').localeCompare(String(b.fileName || ''), undefined, { numeric: true, sensitivity: 'base' });
const product = entries.filter(([k, b]) => !/^(Packaging_Photo|More_Product_Photos)/.test(k) && String(b.mimeType || '').startsWith('image/')).map(([, b]) => b)[0];
const packaging = entries.filter(([k]) => /^Packaging_Photo/.test(k)).map(([, b]) => b)[0];
const more = entries.filter(([k]) => /^More_Product_Photos/.test(k)).map(([, b]) => b).sort(byName);
const maxRefs = Math.min(3, Math.max(0, Math.round(Number(s.max_reference_photos) || 0)));
const list = [];
if (packaging) list.push(['packaging', packaging]);
list.push(['product', product]);
more.slice(0, maxRefs).forEach(b => list.push(['reference', b]));
const ext = { 'image/png': 'png', 'image/webp': 'webp' };
return list.map(([role, photo], i) => ({
  json: {
    role,
    photo_number: i + 1,
    file_name: photo.fileName || `${role}_${i + 1}.${ext[photo.mimeType] || 'jpg'}`,
    mime_type: photo.mimeType || 'image/jpeg',
    skipped_reference_photos: Math.max(0, more.length - maxRefs),
  },
  binary: { photo },
}));

// Reads each photo's pixel size from its file header (JPEG, PNG, WebP).
// The packaging and product photos become the first and last frame, so they get a centered 9:16 crop
// (Kling 3.0 has no aspect-ratio input: the frame image sets the video shape).
// Extra angles are only reference images, so they are kept whole.
const s = $('Set Video Configuration').first().json;
const target = 9 / 16;
const cropOn = s.crop_to_vertical === true || s.crop_to_vertical === 'true';
const label = { packaging: 'The packaging photo', product: 'The product photo', reference: 'Extra product photo' };

function exifOrientation(buf, t) {
  const le = buf.toString('ascii', t, t + 2) === 'II';
  const u16 = o => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = o => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const ifd = t + u32(t + 4);
  const count = u16(ifd);
  for (let k = 0; k < count; k++) {
    const e = ifd + 2 + k * 12;
    if (u16(e) === 0x0112) return u16(e + 8);
  }
  return 1;
}

function imageSize(buf) {
  try {
    if (buf[0] === 0x89 && buf.toString('ascii', 1, 4) === 'PNG') {
      return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20), orientation: 1 };
    }
    if (buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WEBP') {
      const kind = buf.toString('ascii', 12, 16);
      if (kind === 'VP8X') return { w: 1 + buf.readUIntLE(24, 3), h: 1 + buf.readUIntLE(27, 3), orientation: 1 };
      if (kind === 'VP8L') { const b = buf.readUInt32LE(21); return { w: (b & 0x3fff) + 1, h: ((b >> 14) & 0x3fff) + 1, orientation: 1 }; }
      if (kind === 'VP8 ') return { w: buf.readUInt16LE(26) & 0x3fff, h: buf.readUInt16LE(28) & 0x3fff, orientation: 1 };
    }
    if (buf[0] === 0xff && buf[1] === 0xd8) {
      let i = 2;
      let orientation = 1;
      while (i + 9 < buf.length) {
        if (buf[i] !== 0xff) { i++; continue; }
        const marker = buf[i + 1];
        if (marker === 0xff) { i++; continue; }
        if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd8)) { i += 2; continue; }
        const len = buf.readUInt16BE(i + 2);
        if (marker === 0xe1 && buf.toString('ascii', i + 4, i + 8) === 'Exif') {
          try { orientation = exifOrientation(buf, i + 10) || 1; } catch (e) { orientation = 1; }
        }
        if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker)) {
          return { w: buf.readUInt16BE(i + 7), h: buf.readUInt16BE(i + 5), orientation };
        }
        i += 2 + len;
      }
    }
  } catch (e) {}
  return null;
}

const out = [];
const items = $input.all();
for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const name = `${label[item.json.role] || 'Photo'} (${item.json.file_name})`;
  const buf = await this.helpers.getBinaryDataBuffer(idx, 'photo');
  const size = imageSize(buf);
  let crop = { x_percent: 0, y_percent: 0, width_percent: 100, height_percent: 100 };
  let problem = null;
  let w = null;
  let h = null;
  if (!size || !size.w || !size.h) {
    problem = `${name} could not be read. Use a JPG, PNG or WebP photo.`;
  } else {
    // EXIF orientations 5-8 mean the phone stored the photo rotated by 90 degrees.
    const rotated = size.orientation >= 5 && size.orientation <= 8;
    w = rotated ? size.h : size.w;
    h = rotated ? size.w : size.h;
    const ratio = w / h;
    const frame = item.json.role !== 'reference';
    if (frame && cropOn && ratio > target * 1.01) {
      const wp = (target / ratio) * 100;
      crop = { x_percent: Math.round(((100 - wp) / 2) * 1000) / 1000, y_percent: 0, width_percent: Math.round(wp * 1000) / 1000, height_percent: 100 };
    } else if (frame && cropOn && ratio < target * 0.99) {
      const hp = (ratio / target) * 100;
      crop = { x_percent: 0, y_percent: Math.round(((100 - hp) / 2) * 1000) / 1000, width_percent: 100, height_percent: Math.round(hp * 1000) / 1000 };
    }
    const outW = (w * crop.width_percent) / 100;
    const outH = (h * crop.height_percent) / 100;
    if (outW < 300 || outH < 300) problem = `${name} is too small: Kling needs at least 300 x 300 px after cropping (got ${Math.round(outW)} x ${Math.round(outH)}).`;
    else if ((!frame || !cropOn) && (ratio < 0.4 || ratio > 2.5)) problem = `${name} has an aspect ratio Kling does not accept (0.4 to 2.5).`;
  }
  out.push({ json: { ...item.json, width: w, height: h, ...crop, size_problem: problem }, binary: item.binary });
}
return out;

// fal returned one upload URL per photo. Put each photo back next to its URL for the upload step.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const photos = $('Plan Photo Crops').all();
return $input.all().map((item, i) => ({
  json: {
    ...photos[i].json,
    upload_url: item.json.upload_url || '',
    file_url: item.json.file_url || '',
    upload_error: item.json.upload_url ? '' : errText(item.json.error) || 'no upload URL returned',
  },
  binary: photos[i].binary,
}));

// Makes sure every photo is on fal (and cropped), then picks the plan:
// 'unboxing' when there is a packaging photo, 'product reveal' when there is not (no packaging is invented),
// and OpenAI or the template prompts from use_openai.
const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const s = $('Set Video Configuration').first().json;
const photos = $('Attach Photos to URLs').all().map(p => p.json);
const puts = $('Upload Photos to Storage').all().map(p => p.json || {});
const crops = $input.all().map(c => c.json || {});
const problems = [];
const urls = { packaging: '', product: '', reference: [] };
photos.forEach((p, i) => {
  const crop = crops[i] || {};
  const url = crop.image && crop.image.url;
  const name = `${p.role} photo ${p.file_name}`;
  if (p.size_problem) problems.push(p.size_problem);
  else if (p.upload_error) problems.push(`${name}: fal storage did not return an upload URL (${p.upload_error}).`);
  else if (puts[i] && puts[i].error) problems.push(`${name}: upload to fal storage failed (${errText(puts[i].error)}).`);
  else if (!url) problems.push(`${name}: fal could not process the photo (${errText(crop.error) || errText(crop.detail) || 'no image URL returned'}).`);
  else if (p.role === 'reference') urls.reference.push(url);
  else urls[p.role] = url;
});
if (!problems.length && !urls.product) problems.push('No product photo arrived on fal.');
if (problems.length) return [{ json: { route: 'error', ok: false, stage: 'Photo check', problems } }];
const useAi = s.use_openai === true || s.use_openai === 'true';
return [{
  json: {
    route: useAi ? 'ai' : 'template',
    ok: true,
    mode: urls.packaging ? 'unboxing' : 'product reveal',
    product_url: urls.product,
    packaging_url: urls.packaging,
    reference_urls: urls.reference,
    skipped_reference_photos: photos[0] ? photos[0].skipped_reference_photos : 0,
  },
}];

